static bool coordinateOracle(const Scene&s,const Frame&f,const std::string&label){
 if(!check(f.rgba.size()==side*side*4,"complete image for linear normal-map oracle"))return false;
 const RGB texels[]={RGB{{204,128,230}},RGB{{52,182,225}}};auto light=normalized(s.lightVector);light[1]=-light[1];unsigned bad=0,count=0;int maximum=0;RGB witness{};
 auto expected=[&](unsigned x,unsigned y){const double px=(x+.5)*4/side-2,py=2-(y+.5)*4/side;const auto low=s.positions->point[0],high=s.positions->point[2];const double rawS=(px-low[0])/(high[0]-low[0])+s.uv->point[0][0],rawT=(py-low[1])/(high[1]-low[1])+s.uv->point[0][1];const auto scale=s.matrix->scaleFactor.getValue(),translation=s.matrix->translation.getValue();const double u=rawS*scale[0]+translation[0],v=rawT*scale[1]+translation[1];(void)v;
  // GL normalized linear addressing: the first center is .5/width.
  // Both S neighbors wrap independently; the one-row T footprint is the
  // same row twice. Interpolate encoded RGB before decoding the normal.
  const double footprint=u*2-.5;const int left=int(std::floor(footprint));const double fraction=footprint-left;const unsigned a=unsigned((left%2+2)%2),b=(a+1)%2;RGB normal;for(unsigned c=0;c<3;++c)normal[c]=((1-fraction)*texels[a][c]+fraction*texels[b][c])*2/255-1;const double factor=std::max(0.,std::min(1.,dot(normal,light)));RGB out;for(unsigned c=0;c<3;++c)out[c]=255*s.diffuse[c]*factor*s.baseColor[c]/255.;return out;};
 for(unsigned y=side*3/8;y<side*5/8;++y)for(unsigned x=side*3/8;x<side*5/8;++x){RGB e=expected(x,y);size_t p=(size_t(y)*side+x)*4;for(unsigned c=0;c<3;++c){int d=std::abs(int(f.rgba[p+c])-int(std::lround(e[c])));maximum=std::max(maximum,d);bad+=d>3;}bad+=f.rgba[p+3]!=255;++count;}
 witness=expected(side/2,side/2);size_t p=(side/2*side+side/2)*4;std::cout<<"bump_linear_normal "<<label<<" expected="<<witness[0]<<','<<witness[1]<<','<<witness[2]<<" actual="<<unsigned(f.rgba[p])<<','<<unsigned(f.rgba[p+1])<<','<<unsigned(f.rgba[p+2])<<" pixels="<<count<<" bad="<<bad<<" max="<<maximum<<'\n';return check(count>100&&bad==0,"per-pixel authored UV/matrix, repeat bilinear encoded normal, decode and DOT3");
}
static bool coordinates(unsigned samples){Scene s;Harness h(samples);Frame a,b,c;const unsigned char texels[]={204,128,230,52,182,225};s.bump->image.setValue(SbVec2s(2,1),3,texels);s.matrix->scaleFactor.setValue(.125f,.125f);s.matrix->translation.setValue(.125f,.25f);bool ok=h.render(s.root,a,"bump matrix first footprint")&&coordinateOracle(s,a,"bump matrix first footprint");s.matrix->translation.setValue(.625f,.25f);ok &=h.render(s.root,b,"bump matrix second footprint")&&coordinateOracle(s,b,"bump matrix second footprint");s.matrix->translation.setValue(.125f,.25f);for(int i=0;i<4;++i){auto v=s.uv->point[i];v[0]+=4;s.uv->point.set1Value(i,v);}ok &=h.render(s.root,c,"authored UV selects second footprint")&&coordinateOracle(s,c,"authored UV selects second footprint");for(int i=0;i<4;++i){auto v=s.uv->point[i];v[0]-=4;s.uv->point.set1Value(i,v);}ok &=h.render(s.root,c,"UV and matrix recovery")&&coordinateOracle(s,c,"UV and matrix recovery")&&exact(a,c);return ok;}
static bool rtt(unsigned samples,CoinRenderSceneTextureMode route){RttScene graph;auto&producer=graph.producer;Harness h(samples,false,route);Frame a,b,c;bool ok=h.render(graph.root,a,"bump RTT producer/consumer")&&color(a,producer.expected(),"bump RTT independently predicted producer texel");producer.direction({{-.6,.3,.8}});ok &=h.render(graph.root,b,"RTT producer light mutation")&&color(b,producer.expected(),"RTT changed producer");producer.direction({{.6,0,.8}});ok &=h.render(graph.root,c,"RTT producer recovery")&&exact(a,c);auto*extra=new SoPointLight;producer.root->insertChild(extra,2);ok &=h.reject(graph.root,c,"invalid RTT producer multilight");producer.root->removeChild(extra);ok &=h.render(graph.root,b,"RTT malformed recovery")&&exact(a,b);return ok;}

// Independent interpolation over the two authored triangles. The legacy
// tangent frame has S=+X,T=-Y,N=+Z; vertices normalize L and E before
// interpolation, while diffuse normalizes interpolated L again.
static RGB lightingAt(const Scene&s,unsigned x,unsigned y,bool point,RGB lamp,RGB spec,double shine){
 double px=(x+.5)*4/side-2,py=2-(y+.5)*4/side;double u=(px+1.4)/2.7,v=(py+1.3)/2.65;int ix[3];double w[3];if(v<=u){ix[0]=0;ix[1]=1;ix[2]=2;w[0]=1-u;w[1]=u-v;w[2]=v;}else{ix[0]=0;ix[1]=2;ix[2]=3;w[0]=1-v;w[1]=u;w[2]=v-u;}
 RGB l{{0,0,0}},e{{0,0,0}};for(unsigned k=0;k<3;++k){const auto p=s.positions->point[ix[k]];RGB a=point?normalized({{lamp[0]-p[0],lamp[1]-p[1],lamp[2]-p[2]}}):normalized(s.lightVector);RGB b=normalized({{-p[0],-p[1],4-p[2]}});a[1]=-a[1];b[1]=-b[1];for(unsigned c=0;c<3;++c){l[c]+=w[k]*a[c];e[c]+=w[k]*b[c];}}
 RGB n{{s.normal[0]*2./255-1,s.normal[1]*2./255-1,s.normal[2]*2./255-1}},half;for(unsigned c=0;c<3;++c)half[c]=l[c]+e[c];double d=std::max(0.,std::min(1.,dot(n,normalized(l)))),q=std::pow(std::max(0.,std::min(1.,dot(n,normalized(half)))),shine*64);RGB out;for(unsigned c=0;c<3;++c)out[c]=std::min(255.,255*(s.diffuse[c]*d+spec[c]*q));return out;
}
static bool lightOracle(const Scene&s,const Frame&f,bool point,RGB lamp,RGB spec,double shine){unsigned bad=0,count=0;int maximum=0;for(unsigned y=side*3/8;y<side*5/8;++y)for(unsigned x=side*3/8;x<side*5/8;++x){RGB e=lightingAt(s,x,y,point,lamp,spec,shine);size_t p=(size_t(y)*side+x)*4;for(unsigned c=0;c<3;++c){int d=std::abs(int(f.rgba[p+c])-int(std::lround(e[c])));maximum=std::max(maximum,d);bad+=d>3;}bad+=f.rgba[p+3]!=255;++count;}auto e=lightingAt(s,side/2,side/2,point,lamp,spec,shine);size_t p=(side/2*side+side/2)*4;std::cout<<"bump_light point="<<point<<" spec="<<spec[0]<<" expected="<<e[0]<<','<<e[1]<<','<<e[2]<<" actual="<<unsigned(f.rgba[p])<<','<<unsigned(f.rgba[p+1])<<','<<unsigned(f.rgba[p+2])<<" count="<<count<<" bad="<<bad<<" max="<<maximum<<'\n';return check(count>100&&bad==0,"independent vertex light/eye interpolation, DOT3 plus legacy pow(shininess*64)");}
static bool lighting(unsigned samples){Scene s;Harness h(samples);Frame a,b,c;bool ok=true;for(bool point:{false,true}){SoPointLight*pl=nullptr;RGB lamp{{.6,-.3,3}};if(point){s.light->on=FALSE;pl=new SoPointLight;pl->location.setValue(float(lamp[0]),float(lamp[1]),float(lamp[2]));s.root->insertChild(pl,2);}for(RGB spec:{RGB{{0,0,0}},RGB{{.25,.1,.3}}}){s.material->specularColor.setValue(float(spec[0]),float(spec[1]),float(spec[2]));s.material->shininess=.25f;ok &=h.render(s.root,a,"point/directional/specular")&&lightOracle(s,a,point,lamp,spec,.25);s.material->shininess=.5f;ok &=h.render(s.root,b,"shininess mutation")&&lightOracle(s,b,point,lamp,spec,.5);s.material->shininess=.25f;ok &=h.render(s.root,c,"shininess A/B/A")&&exact(a,c);}if(pl){s.root->removeChild(pl);s.light->on=TRUE;}}
 s.material->specularColor.setValue(0,0,0);ok &=h.render(s.root,a,"finite lighting control");s.matrix->translation.setValue(std::numeric_limits<float>::quiet_NaN(),0);ok &=h.reject(s.root,a,"nonfinite bump matrix");s.matrix->translation.setValue(0,0);ok &=h.render(s.root,b,"matrix malformed recovery")&&exact(a,b);auto v=s.uv->point[0];s.uv->point.set1Value(0,SbVec2f(std::numeric_limits<float>::infinity(),0));ok &=h.reject(s.root,b,"nonfinite authored bump coordinate");s.uv->point.set1Value(0,v);ok &=h.render(s.root,c,"coordinate malformed recovery")&&exact(a,c);return ok;}
class PayloadProxy:public Proxy{public:unsigned mutation=0;bool invariant=true,pinned=false;uint64_t revision=0,digest=0;using Proxy::Proxy;
 CoinRenderFramePlan changed(const CoinRenderFramePlan&f){auto p=f;if(!pinned){revision=p.revision;digest=p.textures.empty()?0:p.textures[0].contentDigest;pinned=true;}p.revision=revision;if(!p.textures.empty()){auto&t=p.textures[0];t.contentDigest=digest;if(mutation==3)t.mipmapsRgba={40,180,90,255};if(mutation==1||mutation==2){t.pixelsRgba={70,150,220,255};if(mutation==2){t.width=2;t.height=1;t.pixelsRgba.insert(t.pixelsRgba.end(),{70,150,220,255});}}invariant &=p.revision==revision&&t.contentDigest==digest;std::cout<<"bump_payload_identity mode="<<mutation<<" captured_revision="<<f.revision<<" forwarded_revision="<<p.revision<<" captured_digest="<<f.textures[0].contentDigest<<" forwarded_digest="<<t.contentDigest<<" bytes="<<t.pixelsRgba.size()<<" extent="<<t.width<<'x'<<t.height<<'\n';}return p;}
 CoinRenderSubmitResult submit(const CoinRenderFramePlan&f,CoinRenderTargetP&t)override{plan=changed(f);return real->submit(plan,t);}
 CoinRenderSubmitResult submit(const CoinRenderFramePlan&f,CoinRenderTargetP&t,const CoinRenderFrameReuseDecision&r)override{plan=changed(f);return real->submit(plan,t,r);}
};
static PayloadProxy*mutator(Harness&h){auto*p=new PayloadProxy(std::move(h.proxy->real));h.target->getPimpl()->backend.reset(p);h.proxy=p;return p;}
