 char path[]="/dev/shm/coin-bump-cache-XXXXXX";int fd=mkstemp(path);if(fd<0)return check(false,"RAM trace capture available");unlink(path);std::fflush(stderr);int saved=dup(STDERR_FILENO);if(saved<0||dup2(fd,STDERR_FILENO)<0){if(saved>=0)close(saved);close(fd);return false;}bool ok=h.render(root,f,label);std::fflush(stderr);dup2(saved,STDERR_FILENO);close(saved);lseek(fd,0,SEEK_SET);std::string trace;char bytes[4096];ssize_t got;while((got=read(fd,bytes,sizeof(bytes)))>0)trace.append(bytes,size_t(got));close(fd);std::cerr<<trace;const bool present=trace.find("texture_cache_hit=")!=std::string::npos;const bool hit=trace.find("texture_cache_hit=1")!=std::string::npos;std::cout<<"bump_cache_trace phase="<<label<<" observed="<<present<<" hit="<<hit<<" expected="<<expect<<'\n';return ok&&(expect<0||check(present&&hit==(expect==1),"existing BGFX trace proves repeated texture reuse and changed payload invalidation"));
