static bool sampling(unsigned samples,bool srgb){bool ok=true;const unsigned char pixels[]={240,30,60,255,40,220,70,255,60,80,235,255,230,205,45,255};for(unsigned filter=0;filter<4;++filter){Scene s(true);s.quality->textureQuality=std::array<float,4>{{.1f,.3f,.6f,.8f}}[filter];s.base->image.setValue(SbVec2s(2,2),4,pixels);s.base->wrapS=SoTexture2::CLAMP;s.base->wrapT=SoTexture2::CLAMP;for(int i=0;i<4;++i)s.baseUv->point.set1Value(i,SbVec2f(filter==0?.25f:.5f,filter==0?.25f:.5f));if(filter>=2){const SbVec2f uv[]={SbVec2f(0,0),SbVec2f(128,0),SbVec2f(128,128),SbVec2f(0,128)};s.baseUv->point.setValues(0,4,uv);}Harness h(samples,srgb);if(!h.target)return false;PayloadProxy*proxy=filter>=2?mutator(h):nullptr;if(proxy)proxy->mutation=3;Frame a,b;bool rendered=h.render(s.root,a,"base filter="+std::to_string(filter));ok &=rendered;if(!rendered)continue;bool observed=false;for(const auto&sampler:h.proxy->plan.samplers)observed |=unsigned(sampler.filter)==filter&&sampler.maxAnisotropy==1;ok &=check(observed,"public requested filter captured without anisotropy downgrade");RGB e=s.expected(false);for(unsigned c=0;c<3;++c){double value=0;if(filter==0)value=srgb?decode(pixels[c]/255.):pixels[c]/255.;else if(filter==1){for(unsigned p=0;p<4;++p)value+=(srgb?decode(pixels[p*4+c]/255.):pixels[p*4+c]/255.)/4;}else value=std::array<double,3>{{40/255.,180/255.,90/255.}}[c],value=srgb?decode(value):value;e[c]*=value/(std::array<double,3>{{128/255.,192/255.,64/255.}}[c]);}ok &=color(a,e,"independent base decode and filter/mip sample");ok &=h.render(s.root,b,"filter identical repeat")&&exact(a,b);if(filter>=2)ok &=check(h.proxy->plan.textures.size()>0&&h.proxy->plan.textures[0].mipmapsRgba==std::vector<uint8_t>({40,180,90,255}),"distinct authored lower mip bytes reach executor unchanged");}return ok;}
